$ErrorActionPreference = "Stop"
$base = (Get-Location).Path
if (-not (Test-Path -LiteralPath (Join-Path $base "app\build.gradle.kts"))) { throw "Abra o PowerShell na pasta IPTVPremium que contem app\build.gradle.kts." }
$files = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("")) | ConvertFrom-Json
$staged = @()
foreach ($file in $files) {
    $target = Join-Path $base ($file.path.Replace('/', '\'))
    if (Test-Path -LiteralPath $target) { Write-Host "Preservado: $($file.path)"; continue }
    if ($file.path -eq "build.gradle.kts" -and (Test-Path -LiteralPath (Join-Path $base "build.gradle"))) { continue }
    if ($file.path -eq "settings.gradle.kts" -and (Test-Path -LiteralPath (Join-Path $base "settings.gradle"))) { continue }
    $bytes = [Convert]::FromBase64String($file.content)
    $sha = [Security.Cryptography.SHA256]::Create()
    try { $actual = ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace("-", "").ToLowerInvariant() } finally { $sha.Dispose() }
    if ($actual -ne $file.sha256) { throw "Falha de integridade em $($file.path). Nada foi gravado." }
    $staged += @{ Path = $target; Relative = $file.path; Bytes = $bytes }
}
foreach ($item in $staged) {
    [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($item.Path))
    # CreateNew preserves even a file created concurrently after preflight.
    $stream = [IO.File]::Open($item.Path, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write)
    try { $stream.Write($item.Bytes, 0, $item.Bytes.Length) } finally { $stream.Dispose() }
    Write-Host "Restaurado: $($item.Relative)" -ForegroundColor Green
}
if ($staged.Count -eq 0) { Write-Host "Todos os arquivos de compilacao ja existem. Nenhum foi alterado." -ForegroundColor Green }
else { Write-Host "Restauracao concluida: $($staged.Count) arquivo(s) ausente(s) recuperado(s)." -ForegroundColor Green }
Write-Host "Agora execute: .\gradlew.bat assembleDebug" -ForegroundColor Yellow
Write-Host "O wrapper usa o Java configurado no computador. Se o Java nao for encontrado, envie apenas a mensagem do erro." -ForegroundColor Yellow
